//! Generation of hk tables for any k, without an h11 table in memory.
//!
//! For 0 < k < 11 the hk index is not a coset coordinate (the eo bits it
//! drops are not those of a union of slices), so hk cannot be generated by a
//! BFS on its own indices: each entry is the minimum depth of the h11 cosets
//! it covers. This generator enumerates every h11 coset up to depth
//! `base + 2` instead:
//!
//! 1. a BFS over h11 entries, kept in sorted vectors, up to `prefix_depth`
//!    (8: 7.4M entries, ~60 MB);
//! 2. for each further depth `L`, one depth-first pass from every entry at
//!    `prefix_depth` (one per self-symmetry orbit: symmetric entries are the
//!    same coset) over the canonical move sequences of length
//!    `L - prefix_depth`, marking the hk entries of the cosets reached.
//!
//! Each pass sets only entries that are still unvisited (code 3), and the
//! passes run in increasing `L`, so an entry's first mark is its minimum:
//! all marks of a pass write the same code, and an atomic AND suffices.
//! Every coset at depth `L` is reached, at the end of one of its shortest
//! paths (whose first `prefix_depth` moves end at a coset of the prefix).
//! Paths reaching a coset above its depth are redundant, not wrong: their
//! marks find the entry already set. Children of the roots that are in the
//! prefix (depth `prefix_depth - 1` or `prefix_depth`) are pruned.
//!
//! Group minima (the 4-bit minimum of each group of 62 entries, used for
//! code 0) are set during the passes up to `base`; groups without such an
//! entry get theirs (`base + 1` or `base + 2`, never read by the solver) in a
//! final sequential pass, which gives the same table as the BFS generators.
//!
//! Cost: about `13.3^(base + 2 - prefix_depth)` leaves per root, 2.6e11 for
//! base 10, 1/13 of that for base 9: it depends on the base, not on k.
//! Memory: the table plus ~200 MB (prefix levels and the hash set).

use super::decode_index;
use crate::coord::{cocsep, h11_key, index_sym, reduce_key, N_MSPLIT, N_SLOTS};
use crate::simd::Cube;
use crate::solver::{ALLOWED_AFTER, ALL_MOVES};
use crate::tables::{
    entry_class, entry_low_bits, entry_position, entry_sym_to_rep, h48_rows, packed_class,
    packed_sym_to_rep, Cocsep,
};
use hashbrown::HashSet;
use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering::Relaxed};
use std::time::Instant;

/// Depth of the BFS prefix (see the module docs). Deeper costs memory (depth
/// 9 has 86M entries), shallower costs more redundant DFS paths.
pub const PREFIX_DEPTH: u8 = 8;

/// Settings of a generation run.
#[derive(Clone, Debug)]
pub struct Settings {
    pub k: u32,
    pub base: u8,
    pub threads: usize,
    /// Depth of the BFS prefix (at most `base + 2`).
    pub prefix_depth: u8,
    /// Print progress to stderr.
    pub verbose: bool,
}

/// Entries of h11 cosets, as a sorted vector per depth.
struct Prefix {
    levels: Vec<Vec<u64>>,
    /// The entries of the last two levels (the depths a root's child can
    /// have, when not one deeper).
    // A hashbrown set instead of our own open-addressing one: a lookup that
    // misses is mostly answered by its control bytes, 1/8 of the slots' size
    // (gen 2 8 at 8 threads: 5.4 -> 4.0 s, -26%; d1).
    last_two: HashSet<u64>,
}

/// The h11 entries of the coset of `cube` (one, or more if its corner class
/// has self-symmetries), passed to `visit`.
#[inline(always)]
fn for_each_entry(corners: &Cocsep, cube: Cube, mut visit: impl FnMut(u64)) {
    // SAFETY: cocsep coordinates are below N_COCSEP.
    let entry = unsafe { *corners.entries.get_unchecked(cocsep(cube)) };
    let class = entry_class(entry);
    let edges = cube.transform_edges(entry_sym_to_rep(entry));
    visit(h11_key(class, edges));
    // SAFETY: classes are below N_CLASSES.
    let mut syms = unsafe { *corners.self_symmetries.get_unchecked(class) } & !1;
    while syms != 0 {
        let sym = syms.trailing_zeros() as usize;
        syms ^= syms.isolate_lowest_one();
        visit(h11_key(class, edges.transform_edges(sym)));
    }
}

/// The primary h11 entry of the coset of `c` (one of `for_each_entry`'s).
#[inline(always)]
fn entry(corners: &Cocsep, c: Cube) -> u64 {
    corners.full_key(c)
}

impl Prefix {
    /// BFS on h11 entries up to `depth`.
    fn build(corners: &Cocsep, depth: u8, threads: usize, verbose: bool) -> Prefix {
        let mut start = Vec::new();
        for_each_entry(corners, Cube::solved(), |e| start.push(e));
        start.sort_unstable();
        start.dedup();
        let mut levels = vec![start];
        for d in 1..=depth {
            let last = &levels[usize::from(d - 1)];
            let next_index = AtomicUsize::new(0);
            let chunk = 4096;
            let parts: Vec<Vec<u64>> = crate::parallel::on_threads(threads, |_| {
                let mut out = Vec::new();
                loop {
                    let i = next_index.fetch_add(chunk, Relaxed);
                    if i >= last.len() {
                        break;
                    }
                    for &e in &last[i..(i + chunk).min(last.len())] {
                        let c = decode_index(corners, 11, e);
                        for m in 0..18 {
                            for_each_entry(corners, c.apply_move(m), |x| out.push(x));
                        }
                    }
                }
                out.sort_unstable();
                out.dedup();
                out
            });
            let mut next: Vec<u64> = parts.concat();
            next.sort_unstable();
            next.dedup();
            // Neighbours of depth d - 1 are at depth d - 2, d - 1 or d.
            let older = |e: &u64| {
                let lower = usize::from(d.saturating_sub(2));
                levels[lower..].iter().any(|l| l.binary_search(e).is_ok())
            };
            next.retain(|e| !older(e));
            if verbose {
                super::progress::line(format_args!(
                    "[gen] prefix depth {d}: {} h11 entries",
                    next.len()
                ));
            }
            levels.push(next);
        }
        let n = levels.len();
        let last_two_levels = &levels[n.saturating_sub(2)..];
        let mut last_two = HashSet::with_capacity(last_two_levels.iter().map(Vec::len).sum());
        last_two.extend(last_two_levels.iter().flatten().copied());
        Prefix { levels, last_two }
    }
}

/// The table being generated: rows `rows.start..rows.end` of hk.
pub struct Part<'a> {
    pub words: &'a [AtomicU64],
    /// First slot of the part (`rows.start * N_SLOTS`) and its end.
    pub first_slot: u64,
    pub end_slot: u64,
}

/// Leaf marks of one thread, in a ring: each index is prefetched when it is
/// pushed and applied `RING` pushes later, so that ~`RING` table misses are
/// in flight (batched prefetched writes).
struct Marker<'p, 'a> {
    part: &'p Part<'a>,
    ring: [u64; RING],
    head: usize,
    /// The code written by this pass (`3 ^ clear` is the code).
    clear: u64,
    /// The pass depth, if it also sets group minima (depth <= base).
    group_min: Option<u64>,
}

const RING: usize = 32;

/// An empty ring slot.
const EMPTY: u64 = u64::MAX;

impl Marker<'_, '_> {
    #[inline(always)]
    fn push(&mut self, idx: u64) {
        if idx < self.part.first_slot || idx >= self.part.end_slot {
            return;
        }
        let local = idx - self.part.first_slot;
        prefetch_write(self.part.words, entry_position(local).0);
        // SAFETY: `head` is below RING.
        let old = std::mem::replace(unsafe { self.ring.get_unchecked_mut(self.head) }, local);
        self.head = (self.head + 1) % RING;
        if old != EMPTY {
            self.apply(old);
        }
    }

    #[inline(always)]
    fn apply(&self, local: u64) {
        let (w, sh) = entry_position(local);
        // SAFETY: `local` is below the part's slot count.
        let a = unsafe { self.part.words.get_unchecked(w) };
        if (a.load(Relaxed) >> sh) & 3 != 3 {
            return;
        }
        a.fetch_and(!(self.clear << sh), Relaxed);
        if let Some(depth) = self.group_min {
            set_group_min(self.part.words, w, depth);
        }
    }

    fn flush(&mut self) {
        for i in 0..RING {
            let old = std::mem::replace(&mut self.ring[(self.head + i) % RING], EMPTY);
            if old != EMPTY {
                self.apply(old);
            }
        }
    }
}

/// Set the group minimum of the group of word `w` to `depth` if it is unset
/// (15). Passes run in increasing depth, so the first value set is the
/// minimum; marks of one pass all write the same value.
#[inline(always)]
fn set_group_min(words: &[AtomicU64], w: usize, depth: u64) {
    // SAFETY: `w & !1` is a word of the same group, within the table.
    let g = unsafe { words.get_unchecked(w & !1) };
    if g.load(Relaxed) & 15 == 15 {
        g.fetch_and(!(15 ^ depth), Relaxed);
    }
}

#[inline(always)]
fn prefetch_write(words: &[AtomicU64], w: usize) {
    crate::prefetch::write(words.as_ptr().wrapping_add(w));
}

/// Index constants of `coord::index_sym` for `k`.
fn index_consts(k: u32) -> (u64, u32) {
    (1 << (k + 9), (u32::MAX.unbounded_shr(32 - k)) << (28 - k))
}

/// Generator state shared by the threads.
struct Run<'p, 'a> {
    corners: &'p Cocsep,
    settings: &'p Settings,
    prefix: &'p Prefix,
    part: &'p Part<'a>,
    row_mul: u64,
    eo_mask: u32,
    /// Classes of the part's rows (leaves of other classes are skipped
    /// before their edge coordinates are computed).
    classes: std::ops::RangeInclusive<usize>,
}

impl Run<'_, '_> {
    /// Mark the hk entries of the coset of leaf `c`.
    #[inline(always)]
    fn mark_leaf(&self, c: Cube, marker: &mut Marker) {
        let d = self.corners.packed(cocsep(c));
        let class = packed_class(d);
        if !self.classes.contains(&class) {
            return;
        }
        // SAFETY: classes are below N_CLASSES.
        if unsafe { *self.corners.self_symmetries.get_unchecked(class) } == 1 {
            marker.push(index_sym(
                c,
                packed_sym_to_rep(d),
                class,
                self.row_mul,
                self.eo_mask,
            ));
        } else {
            for_each_entry(self.corners, c, |e| {
                marker.push(reduce_key(e, self.settings.k));
            });
        }
    }

    /// Depth-first walk over canonical sequences of `remaining` more moves
    /// from `c` (`allowed`: the moves allowed next); marks the leaves.
    fn walk(&self, c: Cube, allowed: u32, remaining: u8, prune_prefix: bool, marker: &mut Marker) {
        let mut moves = allowed;
        while moves != 0 {
            let m = moves.trailing_zeros() as usize;
            moves ^= moves.isolate_lowest_one();
            let child = c.apply_move(m);
            if prune_prefix && self.prefix.last_two.contains(&entry(self.corners, child)) {
                continue;
            }
            if remaining == 1 {
                self.mark_leaf(child, marker);
            } else {
                self.walk(child, ALLOWED_AFTER[m / 3], remaining - 1, false, marker);
            }
        }
    }

    /// One pass: mark the cosets at the end of paths of length `depth`.
    fn pass(&self, depth: u8) {
        let base = self.settings.base;
        let code = u64::from(depth.saturating_sub(base).min(3));
        let roots = &self.prefix.levels[usize::from(self.settings.prefix_depth)];
        let next = AtomicUsize::new(0);
        let done = AtomicUsize::new(0);
        let chunk = 64;
        let t0 = Instant::now();
        let finished = std::sync::atomic::AtomicBool::new(false);
        std::thread::scope(|s| {
            // (The progress thread, if any, is spawned before the workers
            // run: one of them is this thread. A reporter's progress bar
            // replaces it.)
            super::progress::start(
                format_args!("h{} depth {depth}", self.settings.k),
                roots.len() as u64,
            );
            if self.settings.verbose && !super::progress::installed() {
                s.spawn(|| {
                    let mut last = Instant::now();
                    while !finished.load(Relaxed) {
                        std::thread::sleep(std::time::Duration::from_millis(100));
                        if last.elapsed().as_secs() >= 10 {
                            last = Instant::now();
                            #[expect(clippy::cast_precision_loss, reason = "a progress estimate")]
                            let f = done.load(Relaxed).min(roots.len()) as f64 / roots.len() as f64;
                            let el = t0.elapsed().as_secs_f64();
                            eprintln!(
                                "[gen h{}] depth {depth}: {:.1}% after {el:.0}s, ~{:.0}s to go",
                                self.settings.k,
                                100.0 * f,
                                el / f.max(1e-9) - el
                            );
                        }
                    }
                });
            }
            crate::parallel::on_threads(self.settings.threads, |_| {
                let mut marker = Marker {
                    part: self.part,
                    ring: [EMPTY; RING],
                    head: 0,
                    clear: 3 ^ code,
                    group_min: (depth <= base).then_some(u64::from(depth)),
                };
                loop {
                    let i = next.fetch_add(chunk, Relaxed);
                    if i >= roots.len() {
                        break;
                    }
                    for &root in &roots[i..(i + chunk).min(roots.len())] {
                        let c = decode_index(self.corners, 11, root);
                        // One root per orbit of entries of the same coset.
                        let mut smallest = root;
                        for_each_entry(self.corners, c, |e| smallest = smallest.min(e));
                        if smallest != root {
                            continue;
                        }
                        let remaining = depth - self.settings.prefix_depth;
                        self.walk(c, ALL_MOVES, remaining, true, &mut marker);
                    }
                    done.fetch_add(chunk, Relaxed);
                    super::progress::advance(chunk as u64);
                }
                marker.flush();
            });
            finished.store(true, Relaxed);
        });
    }
}

/// A generator of hk tables (or of row ranges of them, to bound memory):
/// the BFS prefix is built once.
pub struct Generator<'c> {
    corners: &'c Cocsep,
    settings: Settings,
    prefix: Prefix,
}

impl<'c> Generator<'c> {
    /// Build the BFS prefix.
    ///
    /// # Panics
    /// If `settings` are out of range: `k` above 11, `base` above 12, or a
    /// prefix depth not in `1..=base + 2`.
    #[must_use]
    pub fn new(corners: &'c Cocsep, settings: Settings) -> Generator<'c> {
        let Settings {
            k,
            base,
            prefix_depth,
            threads,
            verbose,
        } = settings;
        assert!(k <= 11 && base <= 12 && (1..=base + 2).contains(&prefix_depth));
        let t0 = Instant::now();
        let prefix = Prefix::build(corners, prefix_depth, threads, verbose);
        if verbose {
            super::progress::line(format_args!(
                "[gen h{k}] prefix in {:.1}s",
                t0.elapsed().as_secs_f64()
            ));
        }
        Generator {
            corners,
            settings,
            prefix,
        }
    }

    /// Generate rows `rows` of hk into `part` (whose words are exactly
    /// those rows).
    ///
    /// # Panics
    /// If `rows` is empty or not within hk, or `part` does not match it.
    pub fn generate(&self, rows: &std::ops::Range<u64>, part: &Part) {
        let Settings {
            k,
            base,
            prefix_depth,
            threads,
            verbose,
        } = self.settings;
        assert!(rows.start < rows.end && rows.end <= h48_rows(k));
        let t0 = Instant::now();
        let n_slots = (rows.end - rows.start) * N_SLOTS as u64;
        assert_eq!(part.words.len() as u64, n_slots / 32);
        assert_eq!(part.first_slot, rows.start * N_SLOTS as u64);
        assert_eq!(part.end_slot, rows.end * N_SLOTS as u64);
        let words = part.words;
        par_chunks(words.len(), threads, |a, b| {
            for w in &words[a..b] {
                w.store(u64::MAX, Relaxed);
            }
        });
        // The prefix levels: every entry of each.
        for (d, level) in self.prefix.levels.iter().enumerate() {
            let depth = u8::try_from(d).unwrap();
            let mut marker = Marker {
                part,
                ring: [EMPTY; RING],
                head: 0,
                clear: 3 ^ u64::from(depth.saturating_sub(base).min(3)),
                group_min: (depth <= base).then_some(u64::from(depth)),
            };
            for &e in level {
                marker.push(reduce_key(e, k));
            }
            marker.flush();
        }
        // (A row is `(class * 70 + msplit) << k | top k eo bits`.)
        let rows_per_class = (N_MSPLIT as u64) << k;
        let first_class = usize::try_from(rows.start / rows_per_class).unwrap();
        let last_class = usize::try_from((rows.end - 1) / rows_per_class).unwrap();
        let (row_mul, eo_mask) = index_consts(k);
        let run = Run {
            corners: self.corners,
            settings: &self.settings,
            prefix: &self.prefix,
            part,
            row_mul,
            eo_mask,
            classes: first_class..=last_class,
        };
        for depth in prefix_depth + 1..=base + 2 {
            let tp = Instant::now();
            run.pass(depth);
            if verbose {
                super::progress::line(format_args!(
                    "[gen h{k}] rows {}..{}: depth {depth} in {:.1}s ({:.1}s for these rows)",
                    rows.start,
                    rows.end,
                    tp.elapsed().as_secs_f64(),
                    t0.elapsed().as_secs_f64()
                ));
            }
        }
        finish_group_minima(words, base, threads);
    }
}

/// Group minima of the groups without an entry of depth <= base: base + 1
/// if one has code 1, else base + 2 if one has code 2 (else they stay 15).
fn finish_group_minima(words: &[AtomicU64], base: u8, threads: usize) {
    par_chunks(words.len() / 2, threads, |a, b| {
        for g in a..b {
            let (w0, w1) = (&words[2 * g], &words[2 * g + 1]);
            let (x0, x1) = (w0.load(Relaxed), w1.load(Relaxed));
            if x0 & 15 != 15 {
                continue;
            }
            let has = |code: u64| {
                [
                    (x0, entry_low_bits(2 * g as u64)),
                    (x1, entry_low_bits(2 * g as u64 + 1)),
                ]
                .iter()
                .any(|&(x, m)| {
                    let lo = x & m;
                    let hi = (x >> 1) & m;
                    let found = match code {
                        1 => lo & !hi,
                        _ => hi & !lo,
                    };
                    found != 0
                })
            };
            let min = if has(1) {
                u64::from(base) + 1
            } else if has(2) {
                u64::from(base) + 2
            } else {
                continue;
            };
            w0.store((x0 & !15) | min, Relaxed);
        }
    });
}

/// Run `f(start, end)` over `n` items in parallel chunks.
fn par_chunks(n: usize, threads: usize, f: impl Fn(usize, usize) + Sync) {
    let chunk = 1 << 16;
    let next = AtomicUsize::new(0);
    crate::parallel::on_threads(threads, |_| loop {
        let a = next.fetch_add(chunk, Relaxed);
        if a >= n {
            break;
        }
        f(a, (a + chunk).min(n));
    });
}
